121	// buildLeafTree builds the tree at the leaf of the UpdateSubtree path.
122	func buildLeafTree(
123		repo *git.Repository,
124		existingTreeHash plumbing.Hash,
125		newEntries []object.TreeEntry,
126		opts UpdateSubtreeOptions,
127	) (plumbing.Hash, error) {
128		if opts.MergeMode == ReplaceAll || existingTreeHash == plumbing.ZeroHash {
129			sorted := make([]object.TreeEntry, len(newEntries))
130			copy(sorted, newEntries)
131			sortTreeEntries(sorted)
132			return storeTree(repo, sorted)
133		}
134	
135		// MergeKeepExisting: read existing tree, merge
136		existingTree, err := repo.TreeObject(existingTreeHash)
137		if err != nil {
138			sorted := make([]object.TreeEntry, len(newEntries))
139			copy(sorted, newEntries)
140			sortTreeEntries(sorted)
141			return storeTree(repo, sorted)
142		}
143	
144		// Build lookup of new entries by name
145		newByName := make(map[string]object.TreeEntry, len(newEntries))
146		for _, e := range newEntries {
147			newByName[e.Name] = e
148		}
149	
150		// Build delete set
151		deleteSet := make(map[string]bool, len(opts.DeleteNames))
152		for _, name := range opts.DeleteNames {
153			deleteSet[name] = true
154		}
155	
156		// Merge: keep existing unless overwritten or deleted
157		merged := make([]object.TreeEntry, 0, len(existingTree.Entries)+len(newEntries))
158		for _, existing := range existingTree.Entries {
159			if deleteSet[existing.Name] {
160				continue
161			}
162			if replacement, ok := newByName[existing.Name]; ok {
163				merged = append(merged, replacement)
164				delete(newByName, existing.Name)
165			} else {
166				merged = append(merged, existing)
167			}
168		}
169		// Add remaining new entries (ones that didn't replace an existing entry)
170		for _, e := range newEntries {
171			if _, stillNew := newByName[e.Name]; stillNew {
172				merged = append(merged, e)
173			}
174		}
175	
176		sortTreeEntries(merged)
177		return storeTree(repo, merged)
178	}
