func hasFullSessionArtifacts(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int) (bool, error) {
	// Check /full/current first.
	if ok, err := hasSessionArtifactsInRef(repo, v2Store, paths.V2FullCurrentRefName, cpID, sessionIdx); err != nil {
		return false, err
	} else if ok {
		return true, nil
	}

	// Check archived /full/* generations.
	archived, err := v2Store.ListArchivedGenerations()
	if err != nil {
		return false, nil //nolint:nilerr // Best-effort: listing failure shouldn't block repair.
