	ag := &CopilotCLIAgent{}
	input := `{"timestamp":"2026-02-09T10:30:00.000Z","cwd":"/path/to/repo","sessionId":"` + testSessionID + `","hookEventName":"SessionEnd","reason":"complete"}`

